"""Independent post-processing; preserves original failed classifications/logs."""
import json
from closure_common import OUT,sha,write_json
def main():
    directory=OUT/'sdk_memory';original=json.loads((directory/'result.json').read_text());boundaries=original['boundaries'];loaded=[r for r in boundaries if r['name']!='unloaded'];unloaded=[r for r in boundaries if r['name']=='unloaded'];growth=original['live_growth_last60000']
    checks=dict(exit_clean=original['process']['exit_code']==0,complete_two_cycles=len(loaded)==6 and len(unloaded)==2,loaded_fd_stable=len(set(r['fds'] for r in loaded))==1,unloaded_fd_stable=len(set(r['fds'] for r in unloaded))==1,two_contact_streams_closed=bool(loaded and unloaded and loaded[0]['fds']-unloaded[0]['fds']==2),live_plateau=len(growth)==2 and max(growth)<1024**2)
    write_json(OUT/'memory_audit.json',dict(status='PASS' if all(checks.values()) else 'FAIL',checks=checks,original_classifier_status=original['status'],original_result_sha256=sha(directory/'result.json'),original_reason='original max(all FDs)==min(all FDs) incorrectly compared loaded scene against unloaded scene; two contact streams are intentionally open only while loaded. No physical tolerance changed.',live_growth_last60000=growth,boundaries=boundaries,scope=original['scope']))
    directory=OUT/'energy_v3';log=(directory/'stdout.log').read_text()+(directory/'stderr.log').read_text();rows=[json.loads(s[12:]) for s in log.splitlines() if s.startswith('CLOSED_WORK ')];paired=[]
    for amplitude in sorted(set(r['amplitude'] for r in rows)):
        group=[r for r in rows if r['proximal_frame_rotation'] and r['amplitude']==amplitude];coarse=next(r for r in group if r['pieces']==64);fine=next(r for r in group if r['pieces']==256);paired.append(dict(amplitude=amplitude,work_coarse=coarse['work'],work_fine=fine['work'],relative_quadrature_change=abs(coarse['work']/fine['work']-1),normalized_circulation=fine['normalized_work'],cross_derivative_curl=fine['cross_derivative_curl']))
    write_json(OUT/'energy_audit.json',dict(execution_status='PASS' if '[ERROR]' not in log and len(rows)==20 else 'FAIL',global_potential_status='FAIL',global_energy_closure='BLOCKED',loops=rows,convergence=paired,source_scope='actual BeamFEM addForce, fixed rest; work F_tip_z dz + torque_prox_y dtheta; physical spatial Y rotation is power-conjugate; midpoints64/256 per side; no time integration or damping in this kernel audit',units='model force*mm; curl dF/dtheta-dtau/dz has model force units',reason='persistent nonzero closed-loop work and cross derivative mismatch preclude an exact state potential for this actual inherited Beam force formulation; distal fixed-frame control alone is insufficient'))
    print('memory checks',checks,'energy loops',len(rows))
if __name__=='__main__':main()
